# Parity test for the FLUX 3 transformer against a tiny random-init
# diffusers Flux3Transformer2DModel (fixture generated by
# tools/gen_fixtures_flux3_model.py, checked in).

if (!requireNamespace("torch", quietly = TRUE) || !torch::torch_is_installed()) {
  exit_file("torch not fully installed")
}
if (!requireNamespace("safetensors", quietly = TRUE)) {
  exit_file("safetensors not installed")
}

library(diffuseR)

fixture_path <- system.file("tinytest", "fixtures", "flux3_model.safetensors",
  package = "diffuseR")
if (fixture_path == "") fixture_path <- "fixtures/flux3_model.safetensors"
if (!file.exists(fixture_path)) exit_file("flux3 model fixtures missing")

fx <- safetensors::safe_load_file(fixture_path, framework = "torch")

max_abs_diff <- function(a, b) {
  as.numeric(torch::torch_max(torch::torch_abs(
    a$to(dtype = torch::torch_float32()) - b$to(dtype = torch::torch_float32())
  )))
}

model <- flux3_transformer(
  in_channels = 8L,
  cond_in_channels = 8L,
  num_layers = 1L,
  num_single_layers = 2L,
  attention_head_dim = 16L,
  num_attention_heads = 2L,
  joint_attention_dim = 32L,
  axes_dims_rope = c(4L, 4L, 4L, 4L),
  flow_map = TRUE
)
model$eval()

# Strict both ways: the R module tree matches the diffusers state dict
weights <- fx[grep("^model\\.", names(fx))]
names(weights) <- sub("^model\\.", "", names(weights))
dests <- c(model$named_parameters(), model$named_buffers())
expect_equal(character(0), setdiff(names(weights), names(dests)))
expect_equal(character(0), setdiff(names(dests), names(weights)))
torch::with_no_grad({
  for (name in names(weights)) dests[[name]]$copy_(weights[[name]])
})

# Position-id builders match the reference exactly
expect_true(max_abs_diff(flux3_prepare_text_ids(7L), fx$txt_ids) == 0)
expect_true(max_abs_diff(flux3_prepare_image_ids(4L, 6L), fx$img_ids) == 0)
expect_true(max_abs_diff(flux3_prepare_image_ids(3L, 5L, l_coord = -1),
  fx$cond_ids) == 0)

# Text-to-image forward
out <- torch::with_no_grad(model(
  hidden_states = fx$hidden,
  encoder_hidden_states = fx$encoder,
  timestep = fx$timestep,
  img_ids = fx$img_ids,
  txt_ids = fx$txt_ids,
  target_timestep = fx$target_timestep
))
expect_equal(as.integer(out$shape), as.integer(fx$out_t2i$shape))
expect_true(max_abs_diff(out, fx$out_t2i) < 1e-5)

# With one reference image
out <- torch::with_no_grad(model(
  hidden_states = fx$hidden,
  encoder_hidden_states = fx$encoder,
  timestep = fx$timestep,
  img_ids = fx$img_ids,
  txt_ids = fx$txt_ids,
  image_cond_hidden_states = fx$cond,
  image_cond_ids = fx$cond_ids,
  target_timestep = fx$target_timestep
))
expect_equal(as.integer(out$shape), as.integer(fx$out_ref$shape))
expect_true(max_abs_diff(out, fx$out_ref) < 1e-5)

# The flow-map checkpoint requires the target timestep
expect_error(model(
  hidden_states = fx$hidden,
  encoder_hidden_states = fx$encoder,
  timestep = fx$timestep,
  img_ids = fx$img_ids,
  txt_ids = fx$txt_ids
), "target_timestep")

# Distilled schedule: static shift 6.93 over linspace(1, 1/16, 16)
sched <- flux3_schedule(16L)
expect_true(max(abs(as.numeric(sched$timesteps) -
  as.numeric(fx$timesteps))) < 1e-3)
expect_true(max(abs(as.numeric(sched$sigmas) -
  as.numeric(fx$sigmas))) < 1e-6)
